static int ctap_process_cbor(uint8_t *req, size_t req_len, uint8_t *resp, size_t *resp_len) {
  if (req_len == 0) return -1;

  cp_pin_uv_auth_token_usage_timer_observer();

  // Use the shared session buffer as the encoder buffer so that
  // large responses (e.g. getAssertion with hmac-secret, ~320 bytes) do not
  // overflow the APDU response buffer (shared_io_buffer, 256 bytes).  When the
  // response fits the APDU buffer it is copied back; otherwise it is streamed
  // via apdu_response_source_set.
  uint8_t *encode_buf = applet_session_scratch.buffer;
  const size_t encode_buf_size = sizeof(applet_session_scratch.buffer);

  CborEncoder encoder;
  cbor_encoder_init(&encoder, encode_buf, encode_buf_size, 0);

  uint8_t cmd;
  if (current_req_src.read) {
    if (ctap_req_read_payload_bytes(0, &cmd, sizeof(cmd)) < 0) {
      ctap_req_lifetime_end();
      return -1;
    }
  } else {
    cmd = *req++;
  }
  req_len--;
  uint8_t status = CTAP2_ERR_UNHANDLED_REQUEST;
  switch (cmd) {
  case CTAP_MAKE_CREDENTIAL:
    DBG_MSG("-----------------MC-------------------\n");
    status = ctap_make_credential(&encoder, req, req_len);
    goto set_resp;
  case CTAP_GET_ASSERTION:
    DBG_MSG("-----------------GA-------------------\n");
    status = ctap_get_assertion(&encoder, req, req_len, false);
    goto set_resp;
  case CTAP_GET_NEXT_ASSERTION:
    DBG_MSG("----------------NEXT------------------\n");
    status = ctap_get_next_assertion(&encoder);
    goto set_resp;
  case CTAP_CLIENT_PIN:
    DBG_MSG("-----------------CP-------------------\n");
    status = ctap_client_pin(&encoder, req, req_len);
    goto set_resp;
  case CTAP_RESET:
    DBG_MSG("----------------RESET-----------------\n");
    status = ctap_reset_data();
    goto set_resp;
  case CTAP_CRED_MANAGE_LEGACY: // compatible with old libfido2
    cmd = CTAP_CREDENTIAL_MANAGEMENT;
    CNK_FALLTHROUGH;
  case CTAP_CREDENTIAL_MANAGEMENT:
    DBG_MSG("----------------CM--------------------\n");
    status = ctap_credential_management(&encoder, req, req_len);
    goto set_resp;
  case CTAP_SELECTION:
    DBG_MSG("----------------SELECTION-------------\n");
    status = ctap_selection();
    goto set_resp;
  case CTAP_LARGE_BLOBS:
    DBG_MSG("----------------LB--------------------\n");
    memset(&response_stream_state, 0, sizeof(response_stream_state));
    status = ctap_large_blobs(req, req_len);
    if (status == 0 && response_stream_state.prepared) {
      *resp = 0;
      *resp_len = 0;
      if (!hid_cbor_stream_response_active)
        apdu_response_source_set((uint32_t)response_stream_state.total_len, SW_NO_ERROR,
                                ctap_response_stream_read_at, NULL, &response_stream_state);
      goto finish;
    }
    goto set_resp;
  case CTAP_CONFIG:
    DBG_MSG("----------------CONFIG----------------\n");
    status = ctap_config(&encoder, req, req_len);
    goto set_resp;
  default:
    *resp = CTAP2_ERR_UNHANDLED_REQUEST;
    goto finish_status_only;
  }

set_resp:
  *resp = status;
  SET_RESP();
  if (*resp_len > APDU_BUFFER_SIZE && status == 0) {
    // Prepend the status byte by shifting the CBOR data right.
    size_t cbor_len = *resp_len - 1;
    memmove(encode_buf + 1, encode_buf, cbor_len);
    encode_buf[0] = *resp;
    if (!hid_cbor_stream_response_active) {
      // Response is too large for the APDU buffer; stream it via GET RESPONSE.
      apdu_response_source_set((uint32_t)*resp_len, SW_NO_ERROR, apdu_response_source_read_memory, NULL, encode_buf);
      *resp_len = 1; // initial APDU payload: status byte only
    }
  } else if (*resp_len > 1 && status == 0) {
    memmove(resp + 1, encode_buf, *resp_len - 1);
  }
  goto finish;

finish_status_only:
  *resp_len = 1;

finish:
  last_cmd = cmd;
  if (*resp != 0) { // do not allow GET_NEXT_ASSERTION if error occurs
    last_cmd = CTAP_INVALID_CMD;
  }
  return 0;
}

static int __attribute__((noinline)) ctap_prepare_make_credential_apdu_response(uint8_t *req, size_t req_len,
                                                                                RAPDU *rapdu) {
  uint8_t *resp = rapdu->data;
  size_t resp_len = APDU_BUFFER_SIZE;

  memset(&response_stream_state, 0, sizeof(response_stream_state));
  stream_resp_base = resp;
  stream_make_credential_response = true;

  CborEncoder encoder;
  cbor_encoder_init(&encoder, resp + 1, resp_len - 1, 0);

  uint8_t status = ctap_make_credential(&encoder, req + 1, req_len - 1);
  ctap_req_lifetime_end();

  stream_make_credential_response = false;
  stream_resp_base = NULL;

  resp[0] = status;
  last_cmd = CTAP_MAKE_CREDENTIAL;
  if (status != 0) last_cmd = CTAP_INVALID_CMD;

  if (status == 0 && response_stream_state.prepared) {
    apdu_response_source_set((uint32_t)response_stream_state.total_len, SW_NO_ERROR, ctap_response_stream_read_at,
                             NULL, &response_stream_state);
    return 0;
  }

  rapdu->len = status == 0 ? (uint16_t)(1 + cbor_encoder_get_buffer_size(&encoder, resp + 1)) : 1;
  return 0;
}

int __attribute__((noinline)) u2f_register(const CAPDU *capdu, RAPDU *rapdu) {
  if (LC != 64) EXCEPT(SW_WRONG_LENGTH);

  if (!is_nfc()) {
    start_blinking(2);
    if (get_touch_result() == TOUCH_NO) EXCEPT(SW_CONDITIONS_NOT_SATISFIED);
    set_touch_result(TOUCH_NO);
    stop_blinking();
  }

  U2F_REGISTER_REQ *req = (U2F_REGISTER_REQ *)DATA;
  U2F_register_prefix *resp = (U2F_register_prefix *)u2f_register_stream_buffer;
  credential_id kh;
  uint8_t digest[SHA256_DIGEST_LENGTH];
  uint8_t pubkey[PUB_KEY_SIZE];
  sha256_ctx_t sha256;

  memcpy(kh.rp_id_hash, req->appId, U2F_APPID_SIZE);
  int err = generate_key_handle(&kh, pubkey, COSE_ALG_ES256, 0, CRED_PROTECT_VERIFICATION_OPTIONAL, false);
  if (err < 0) return err;

  // there are overlaps between req and resp
  sha256_init(&sha256);
  sha256_update(&sha256, (uint8_t[]){0x00}, 1);
  sha256_update(&sha256, req->appId, U2F_APPID_SIZE);
  sha256_update(&sha256, req->chal, U2F_CHAL_SIZE);

  // build response
  // REGISTER ID (1)
  resp->register_id = U2F_REGISTER_ID;
  // PUBLIC KEY (65)
  resp->pub_key.pointFormat = U2F_POINT_UNCOMPRESSED;
  memcpy(resp->pub_key.x, pubkey, PUB_KEY_SIZE); // accessing out of bounds is intentional.
  // KEY HANDLE LENGTH (1)
  resp->key_handle_len = sizeof(credential_id);
  memcpy(&resp->key_handle, &kh, sizeof(credential_id));
  int cert_len = get_file_size(CTAP_CERT_FILE);
  if (cert_len < 0 || cert_len > U2F_MAX_ATT_CERT_SIZE) return -1;
  // SIG (var)
  sha256_update(&sha256, (const uint8_t *)&kh, sizeof(credential_id));
  sha256_update(&sha256, (const uint8_t *)&resp->pub_key, U2F_EC_PUB_KEY_SIZE + 1);
  sha256_final(&sha256, digest);
  size_t signature_len =
      sign_with_device_key(digest, PRIVATE_KEY_LENGTH[SECP256R1], u2f_register_stream_buffer + sizeof(*resp));
  if (signature_len == 0 || signature_len > U2F_MAX_EC_SIG_SIZE) return -1;

  u2f_register_stream_state.cert_len = (uint16_t)cert_len;
  u2f_register_stream_state.sig_len = (uint8_t)signature_len;
  apdu_response_source_set((uint32_t)sizeof(*resp) + (uint32_t)cert_len + (uint32_t)signature_len, SW_NO_ERROR,
                           u2f_register_stream_read_at, NULL, &u2f_register_stream_state);
  LL = 0;

  return 0;
}

static void CTAPHID_Execute_Msg(void) {
  if (channel.bcnt_total < 7) {
    CTAPHID_SendErrorResponse(channel.cid, ERR_INVALID_LEN);
    return;
  }

  if (acquire_apdu_interface(DEVICE_APPLET_SESSION_CTAPHID, BUFFER_OWNER_CTAPHID) != 0) {
    CTAPHID_SendErrorResponse(channel.cid, ERR_CHANNEL_BUSY);
    return;
  }
  rx_session_owned = 0; // The command now owns the session through response completion.
  ctap_req_src_t req_src;
  uint8_t *req = CTAPHID_GetRequestBuffer(&req_src);
  uint8_t error_code = ERR_OTHER;
  CAPDU *capdu = &apdu_cmd;
  RAPDU *rapdu = &apdu_resp;
  uint8_t req_head[7];
  if (CTAPHID_ReadPreparedRequest(req, &req_src, 0, req_head, sizeof(req_head)) < 0) {
    goto request_error;
  }
  CLA = req_head[0];
  INS = req_head[1];
  P1 = req_head[2];
  P2 = req_head[3];
  LC = ((uint16_t)req_head[5] << 8) | req_head[6];
  if (LC > channel.bcnt_total - 7) {
    error_code = ERR_INVALID_LEN;
    goto request_error;
  }
  const size_t le_len = channel.bcnt_total - 7 - LC;
  if (le_len == 2) {
    uint8_t le[2];
    if (CTAPHID_ReadPreparedRequest(req, &req_src, 7 + LC, le, sizeof(le)) < 0) {
      goto request_error;
    }
    LE = ((uint16_t)le[0] << 8) | le[1];
    if (LE == 0) LE = 0x10000;
  } else if (le_len == 0) {
    LE = 0x10000;
  } else {
    error_code = ERR_INVALID_LEN;
    goto request_error;
  }
  capdu->extended = 1;
  DATA = req ? req + 7 : req_head;
  RDATA = shared_io_buffer;
  if (req) {
    ctap_process_apdu_with_src(capdu, rapdu, CTAP_SRC_HID);
  } else {
    ctap_req_src_t payload_src;
    CTAPHID_PayloadSource(&req_src, 7, LC, &payload_src);
    ctap_process_apdu_source_with_src(capdu, &payload_src, rapdu, CTAP_SRC_HID);
  }
  CTAPHID_ClosePreparedRequest();
  const APDU_RESPONSE_SOURCE_VIEW *apdu_source = apdu_response_source_view();
  if (apdu_source && apdu_source->total_len - apdu_source->offset <= capdu->le) {
    CTAPHID_TxSource source = {
        .total_len = apdu_source->total_len - apdu_source->offset + 2,
        .read = CTAPHID_APDUResponseRead,
        .close = CTAPHID_CloseAPDUResponse,
        .ctx = (void *)apdu_source,
    };
    const int send_ret = CTAPHID_SendStreamSource(channel.cid, channel.cmd, &source);
    if (send_ret != 0) {
      device_applet_session_release(DEVICE_APPLET_SESSION_CTAPHID);
      CTAPHID_SendErrorResponse(channel.cid, ERR_OTHER);
      return;
    }
    return;
  }
  if (apdu_source && apdu_response_source_output(rapdu, capdu->le) != 0) {
    release_apdu_interface(DEVICE_APPLET_SESSION_CTAPHID, BUFFER_OWNER_CTAPHID);
    CTAPHID_SendErrorResponse(channel.cid, ERR_OTHER);
    return;
  }
  const uint8_t response_pending = apdu_response_source_active();
  shared_io_buffer[LL] = HI(SW);
  shared_io_buffer[LL + 1] = LO(SW);
  const int send_ret = CTAPHID_SendResponse(channel.cid, channel.cmd, shared_io_buffer, LL + 2);
  CTAPHID_ReleaseSharedBuffer();
  if (send_ret != 0) {
    device_applet_session_release(DEVICE_APPLET_SESSION_CTAPHID);
    CTAPHID_SendErrorResponse(channel.cid, ERR_OTHER);
    return;
  }
  if (!response_pending) device_applet_session_release(DEVICE_APPLET_SESSION_CTAPHID);
  return;

request_error:
  CTAPHID_ClosePreparedRequest();
  release_apdu_interface(DEVICE_APPLET_SESSION_CTAPHID, BUFFER_OWNER_CTAPHID);
  CTAPHID_SendErrorResponse(channel.cid, error_code);
}
